@Component("operation-handler")
@ProcessingGroup("operation-processing-group")
public class OperationEventHandler {
	
	// core constructor
	OperationEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateOperationEvent
     */
    @EventHandler
    public void handle( CreateOperationEvent event) {
        entityManager.persist(new Operation(event.getOperationId(), event.getOperationNumber(), event.getName(), event.getSetupTime(), event.getStandardCycleTime(), event.getRouting(), event.getWorkCenter(), event.getInspectionPlan(), event.getOperationType()));
    }

    /*
     * @param	event UpdateOperationEvent
     */
    @EventHandler
    public Operation handle( UpdateOperationEvent event) {
    	entityManager.merge(new Operation(event.getOperationId(), event.getOperationNumber(), event.getName(), event.getSetupTime(), event.getStandardCycleTime(), event.getRouting(), event.getWorkCenter(), event.getInspectionPlan(), event.getOperationType()));
    }
    
    /*
     * @param	event DeleteOperationEvent
     */
    @EventHandler
    public void on( DeleteOperationEvent event) {
    	Operation entity = new Operation();
   
    	// ------------------------------------------
    	// apply the OperationId
    	// ------------------------------------------
    	entity.setOperationId( event.getOperationId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final OperationRepository operationEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(OperationEventHandler.class.getName());

}
